import React, { useEffect, useRef, useState, useCallback } from "react";
import Avatar from "./Avatar";
import { useAuth } from "../context/AuthContext";
import { getRoomName, fmtTime, fmtDate } from "../utils/helpers";
import { getChatHistory } from "../services/api";
import { wsService } from "../services/websocket";

export default function ChatWindow({ room, messages, onNewMessage }) {
  const { username } = useAuth();
  const [text, setText] = useState("");
  const [loading, setLoading] = useState(false);
  const [fetched, setFetched] = useState(false);
  const bottomRef = useRef(null);
  const inputRef = useRef(null);
  const isGroup = room?.isGroup || room?.group;
  const roomName = room ? getRoomName(room, username) : "";

  // Fetch history on room change
  useEffect(() => {
    if (!room) return;
    setFetched(false);
    setLoading(true);
    getChatHistory(room.id)
      .then(({ data }) => { onNewMessage(room.id, data, true); setFetched(true); })
      .catch(() => setFetched(true))
      .finally(() => setLoading(false));
  }, [room?.id]);

  // Subscribe room on WS
  useEffect(() => {
    if (!room || !wsService.connected) return;
    wsService.subscribeRoom(room.id, (msg) => onNewMessage(room.id, [msg], false));
    return () => {};
  }, [room?.id, wsService.connected]);

  // Scroll to bottom on new messages
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages?.length]);

  const send = useCallback(() => {
    const content = text.trim();
    if (!content || !room) return;
    if (!wsService.connected) { alert("Not connected to server"); return; }
    wsService.sendMessage(room.id, content, username, username);
    setText("");
    inputRef.current?.focus();
  }, [text, room, username]);

  const handleKey = (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
  };

  if (!room) return <EmptyState />;

  const grouped = groupMessagesByDate(messages || []);

  return (
    <div className="flex flex-col h-full bg-crisp-bg">
      {/* Header */}
      <div className="flex items-center gap-3 px-5 py-4 bg-crisp-surface border-b border-crisp-border flex-shrink-0">
        <Avatar name={roomName} size="md" square={isGroup} />
        <div className="flex-1 min-w-0">
          <div className="font-display font-bold text-base text-crisp-text truncate">{roomName}</div>
          <div className="text-xs text-crisp-muted font-body mt-0.5">
            {isGroup
              ? `${(room.participantIds || []).length} members`
              : (room.participantIds || []).filter(u => u !== username).join(" & ")}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-crisp-card border border-crisp-border">
            <span className={`w-1.5 h-1.5 rounded-full ${wsService.connected ? "bg-crisp-green" : "bg-crisp-amber animate-pulse2"}`} />
            <span className="text-xs font-mono text-crisp-muted">{wsService.connected ? "Live" : "Offline"}</span>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-1">
        {loading && (
          <div className="flex justify-center py-8">
            <div className="flex gap-1">
              {[0,1,2].map(i=>(
                <div key={i} className="w-2 h-2 rounded-full bg-crisp-border2 animate-pulse2"
                  style={{animationDelay:`${i*0.15}s`}} />
              ))}
            </div>
          </div>
        )}
        {!loading && fetched && (!messages || messages.length === 0) && (
          <div className="flex flex-col items-center justify-center h-full gap-3 py-16">
            <div className="text-3xl opacity-30">💬</div>
            <div className="text-crisp-muted text-sm font-body">No messages yet. Say hello!</div>
          </div>
        )}

        {grouped.map(({ date, msgs }) => (
          <div key={date}>
            <div className="flex items-center gap-3 my-4">
              <div className="flex-1 h-px bg-crisp-border" />
              <span className="text-xs text-crisp-muted font-mono px-3 py-1 bg-crisp-card border border-crisp-border rounded-full">
                {date}
              </span>
              <div className="flex-1 h-px bg-crisp-border" />
            </div>
            {msgs.map((msg, i) => (
              <MessageBubble
                key={msg.id || `${msg.roomId}-${i}`}
                msg={msg}
                isOwn={msg.senderId === username}
                showSender={isGroup && msg.senderId !== username}
                prevMsg={i > 0 ? msgs[i - 1] : null}
              />
            ))}
          </div>
        ))}
        <div ref={bottomRef} />
      </div>

      {/* Input */}
      <div className="px-4 py-4 bg-crisp-surface border-t border-crisp-border flex-shrink-0">
        <div className="flex items-end gap-3 bg-crisp-card border border-crisp-border2 rounded-2xl
          px-4 py-3 focus-within:border-crisp-accent/50 transition-all duration-200">
          <textarea
            ref={inputRef}
            className="flex-1 bg-transparent text-crisp-text text-sm font-body outline-none resize-none
              placeholder:text-crisp-muted leading-relaxed max-h-32"
            placeholder={`Message ${roomName}...`}
            rows={1}
            value={text}
            onChange={(e) => {
              setText(e.target.value);
              e.target.style.height = "auto";
              e.target.style.height = Math.min(e.target.scrollHeight, 128) + "px";
            }}
            onKeyDown={handleKey}
          />
          <button
            onClick={send}
            disabled={!text.trim()}
            className="w-9 h-9 bg-crisp-accent hover:bg-crisp-accent2 disabled:opacity-30
              disabled:cursor-not-allowed rounded-xl flex items-center justify-center flex-shrink-0
              transition-all duration-200 active:scale-95 shadow-md shadow-crisp-accent/20"
          >
            <SendIcon />
          </button>
        </div>
        <div className="text-center mt-2 text-[10px] text-crisp-muted font-mono">
          Enter to send · Shift+Enter for new line
        </div>
      </div>
    </div>
  );
}

function MessageBubble({ msg, isOwn, showSender, prevMsg }) {
  const sameAuthor = prevMsg?.senderId === msg.senderId;
  const gap = sameAuthor ? "mt-1" : "mt-3";

  return (
    <div className={`flex items-end gap-2.5 ${isOwn ? "flex-row-reverse" : ""} ${gap} animate-msgIn`}>
      {/* Avatar spacer for own, real for others */}
      <div className="w-8 flex-shrink-0">
        {!isOwn && !sameAuthor && <Avatar name={msg.senderName || msg.senderId} size="sm" />}
      </div>

      <div className={`flex flex-col max-w-[70%] ${isOwn ? "items-end" : "items-start"}`}>
        {showSender && !sameAuthor && (
          <span className="text-[11px] text-crisp-muted font-display font-semibold mb-1 ml-1">
            {msg.senderName || msg.senderId}
          </span>
        )}
        <div className={isOwn ? "bubble-own" : "bubble-them"}>
          {msg.content}
        </div>
        <span className="text-[10px] text-crisp-muted font-mono mt-1 mx-1">
          {fmtTime(msg.timestamp)}
        </span>
      </div>
    </div>
  );
}

