function groupMessagesByDate(messages) {
  const map = {};
  messages.forEach((msg) => {
    const key = fmtDate(msg.timestamp) || "Today";
    if (!map[key]) map[key] = [];
    map[key].push(msg);
  });
  return Object.entries(map).map(([date, msgs]) => ({ date, msgs }));
}

